from __future__ import annotations
from airflow.decorators import dag, task
import pendulum

@dag(
    schedule="@daily",
    start_date=pendulum.datetime(2024, 1, 1, tz="UTC"),
    catchup=False,
    tags=["dynamic-mapping"],
)
def dynamic_file_processing():
    @task
    def list_files() -> list[str]:
        # In reality: list an S3 prefix; count is unknown until now
        return ["orders_a.csv", "orders_b.csv", "orders_c.csv"]

    @task
    def process_file(path: str) -> int:
        # Each mapped instance handles exactly one file
        rows = {"orders_a.csv": 1200, "orders_b.csv": 980, "orders_c.csv": 1500}[path]
        print(f"processing {path}: {rows} rows")
        return rows

    @task
    def summarize(counts: list[int]) -> int:
        total = sum(counts)
        print(f"processed {len(counts)} files, {total} total rows")
        return total

    files = list_files()
    counts = process_file.expand(path=files)   # fan-out: one instance per file
    summarize(counts)                          # fan-in: reduce

dynamic_file_processing()
